import { useEffect, useMemo, useRef, useState, type ReactNode } from 'react';
import { Activity, ArrowDownToLine, ArrowUp, Bell, CheckCircle2, ChevronDown, ChevronRight, Clock3, Copy, Eye, Gift, MessageSquareText, MoreHorizontal, Plus, Radar, RefreshCw, Repeat2, Search, Settings2, ShieldCheck, ThumbsUp, Trash2, UserMinus, UserPlus, UserRound, X, Zap } from 'lucide-react';
import { AnyObject, EmptyState, Pagination, PageHeader, Panel, StatusPill, api, formatDate, formatDuration, levelText, sourceText, statusText, taskText } from '../core';

export function DashboardPage({ stats, accounts, jobs, runs, onNavigate }: AnyObject) {
  const cards = [
    { label: '有效账号', value: stats.activeAccounts || 0, note: `共 ${stats.accounts || 0} 个账号`, icon: UserRound, tone: 'primary' },
    { label: '今日发现', value: stats.lotteriesToday || 0, note: '已写入抽奖记录', icon: Gift, tone: 'info' },
    { label: '今日完成任务', value: stats.successToday || 0, note: `共运行 ${stats.runsToday || 0} 次`, icon: CheckCircle2, tone: 'success' },
    { label: '待处理中奖', value: stats.winsUnread || 0, note: '建议及时核对', icon: Bell, tone: 'warning' }
  ];
  return <>
    <PageHeader title="运行总览" description="账号任务按顺序执行，所有结果以结构化事件统计。" actions={<button className="button primary" onClick={() => onNavigate('accounts')}><Plus size={18} />添加账号</button>} />
    <section className="metric-grid">{cards.map(card => { const Icon = card.icon; return <article className={`metric-card tone-${card.tone}`} key={card.label}><div className="metric-icon"><Icon size={21} /></div><div><span>{card.label}</span><strong>{card.value}</strong><small>{card.note}</small></div></article>; })}</section>
    <section className="two-column">
      <Panel title="任务队列" subtitle="当前串行调度状态" actions={<button className="button ghost compact" onClick={() => onNavigate('jobs')}>查看任务<ChevronRight size={16} /></button>}>
        <div className="queue-summary"><div><strong>{jobs.filter((item: AnyObject) => item.status === 'running').length}</strong><span>运行中</span></div><div><strong>{jobs.filter((item: AnyObject) => item.status === 'pending').length}</strong><span>排队中</span></div><div><strong>{runs.filter((item: AnyObject) => item.status === 'failed').length}</strong><span>近期失败</span></div></div>
      </Panel>
      <Panel title="账号状态" subtitle="最近验证结果" actions={<button className="button ghost compact" onClick={() => onNavigate('accounts')}>管理账号<ChevronRight size={16} /></button>}>
        <div className="compact-list">{accounts.slice(0, 4).map((account: AnyObject) => <div className="compact-row" key={account.id}><span className="avatar">{(account.name || '账').slice(0, 1)}</span><div><strong>{account.name || `账号 ${account.id}`}</strong><small>UID {account.uid || '未识别'}</small></div><StatusPill status={account.cookie_status} /></div>)}{!accounts.length && <EmptyState title="还没有账号" />}</div>
      </Panel>
    </section>
    <Panel title="最近运行" subtitle="展示真实发现、候选、参与和失败数量" actions={<button className="button ghost compact" onClick={() => onNavigate('jobs')}>查看日志<ChevronRight size={16} /></button>}>
      <div className="responsive-table"><table><thead><tr><th>账号</th><th>任务</th><th>状态</th><th>开始时间</th><th>耗时</th><th>结果</th></tr></thead><tbody>{runs.slice(0, 6).map((run: AnyObject) => <tr key={run.id}><td data-label="账号"><strong>{run.account_name || `账号 ${run.account_id}`}</strong></td><td data-label="任务">{taskText[run.type] || run.type}</td><td data-label="状态"><StatusPill status={run.status} /></td><td data-label="开始时间">{formatDate(run.started_at)}</td><td data-label="耗时">{formatDuration(run.started_at, run.finished_at)}</td><td data-label="结果">发现 {run.discovered_count || 0} · 成功 {run.participated_count || run.success_count || 0} · 部分 {run.partial_count || 0} · 失败 {run.failed_count || 0}</td></tr>)}</tbody></table>{!runs.length && <EmptyState title="还没有运行记录" />}</div>
    </Panel>
  </>;
}

export function AccountsPage({ accounts, onReload, onNotify, onAdd, onRun, onEditConfig, onSchedules }: AnyObject) {
  const [search, setSearch] = useState(''); const [verifying, setVerifying] = useState<number | 'all' | null>(null);
  const [commentCounts, setCommentCounts] = useState<Record<number, number>>({}); const [commentBusy, setCommentBusy] = useState<number | null>(null);
  const filtered = useMemo(() => accounts.filter((item: AnyObject) => `${item.name} ${item.note} ${item.uid}`.toLowerCase().includes(search.toLowerCase())), [accounts, search]);
  useEffect(() => { let active = true; void Promise.all(accounts.map(async (account: AnyObject) => { try { const status = await api<AnyObject>(`/api/accounts/${account.id}/comment-backfill/status`); return [Number(account.id), Number(status.pending) || 0] as const; } catch { return [Number(account.id), 0] as const; } })).then(rows => { if (active) setCommentCounts(Object.fromEntries(rows)); }); return () => { active = false; }; }, [accounts]);
  async function verifyAll() { setVerifying('all'); try { const result = await api<AnyObject>('/api/accounts/verify-all', { method: 'POST' }); const valid = result.results.filter((item: AnyObject) => item.ok).length; onNotify(`验证完成：${valid}/${result.results.length} 个账号有效`); } catch (error) { onNotify((error as Error).message); } finally { await onReload(); setVerifying(null); } }
  async function verifyOne(id: number) { setVerifying(id); try { await api(`/api/accounts/${id}/verify`, { method: 'POST' }); onNotify('账号验证成功'); } catch (error) { onNotify((error as Error).message); } finally { await onReload(); setVerifying(null); } }
  async function startCommentBackfill(id: number) { setCommentBusy(id); try { const status = await api<AnyObject>(`/api/accounts/${id}/comment-backfill/status`); const pending = Number(status.pending) || 0; setCommentCounts(value => ({ ...value, [id]: pending })); if (!pending) { onNotify('当前账号没有待补充评论的记录'); return; } if (!window.confirm(`当前账号有 ${pending} 条待补充评论。本次最多处理 20 条，只发表评论，不会重复关注、点赞或转发。确定继续吗？`)) return; const result = await api<AnyObject>(`/api/accounts/${id}/comment-backfill`, { method: 'POST', body: JSON.stringify({ limit: 20 }) }); onNotify(result.accepted ? '补充评论任务已加入串行队列' : result.reason || '没有待补充记录'); await onReload(); } catch (error) { onNotify((error as Error).message); } finally { setCommentBusy(null); } }
  return <>
    <PageHeader title="账号管理" description="Cookie 加密保存，添加或扫码成功后会立即验证。" actions={<button className="button primary" onClick={onAdd}><Plus size={18} />添加账号</button>} />
    <Panel><div className="toolbar"><label className="search-input"><Search size={18} /><input value={search} onChange={event => setSearch(event.target.value)} placeholder="搜索昵称、备注或 UID" /></label><button className="button secondary" onClick={verifyAll} disabled={verifying !== null}><RefreshCw size={17} className={verifying === 'all' ? 'spin' : ''} />验证全部账号</button></div>
      <div className="responsive-table"><table><thead><tr><th>账号</th><th>UID</th><th>Cookie 状态</th><th>最近验证</th><th>常用操作</th></tr></thead><tbody>{filtered.map((account: AnyObject) => <tr key={account.id}><td data-label="账号"><div className="identity"><span className="avatar">{(account.name || '账').slice(0, 1)}</span><div><strong>{account.name || `账号 ${account.id}`}</strong><small>{account.note || '未设置备注'}</small></div></div></td><td data-label="UID" className="mono">{account.uid || '—'}</td><td data-label="Cookie 状态"><StatusPill status={account.cookie_status} />{account.verification_error && <small className="field-error">{account.verification_error}</small>}</td><td data-label="最近验证">{formatDate(account.last_verified_at)}</td><td data-label="操作"><div className="account-actions"><button className="button primary compact" onClick={() => onRun(account.id, 'start')}><Zap size={16} />执行抽奖</button><button className="button secondary compact" onClick={() => onRun(account.id, 'discover')}><Radar size={16} />仅发现</button><details className="action-menu"><summary className="icon-button" aria-label="更多账号操作"><MoreHorizontal size={19} /></summary><div className="action-popover"><button onClick={() => verifyOne(account.id)} disabled={verifying !== null}><ShieldCheck size={16} />验证账号</button><button onClick={() => onRun(account.id, 'check')}><Eye size={16} />中奖检测</button><button onClick={() => startCommentBackfill(account.id)} disabled={commentBusy !== null || !commentCounts[account.id]}><MessageSquareText size={16} />补充历史评论（{commentCounts[account.id] || 0} 条）</button><button onClick={() => onSchedules(account.id)}><Clock3 size={16} />定时任务</button><button onClick={() => onEditConfig(account.id)}><Settings2 size={16} />账号配置</button><button className="danger-text" onClick={async () => { if (!window.confirm('确定删除这个账号及其历史记录吗？')) return; await api(`/api/accounts/${account.id}`, { method: 'DELETE' }); onNotify('账号已删除'); onReload(); }}><Trash2 size={16} />删除账号</button></div></details></div></td></tr>)}</tbody></table>{!filtered.length && <EmptyState title="没有匹配的账号" description="调整搜索条件或添加新账号。" />}</div>
    </Panel>
  </>;
}

